fix_code:
public static void solve() throws IOException {
	int n=nextInt();
	int[]a=new int[n],b=new int[n];
	Integer[]arr=new Integer[n];
	for(int i=0;i<n;i++) {
		a[i]=nextInt();
		b[i]=nextInt();
		arr[i]=i;//存下标
	}
	Arrays.sort(arr,(o1,o2)->b[o1]-b[o2]);
	long ans=0;
	for(int i=0;i<n;i++) {
		int t=arr[i];
		int l=0,r=i-1,mid,ind=i;
		while(l<=r) {
			mid=l+(r-l)/2;
			if(b[arr[mid]]>=a[t]) {
				ind=mid;
				r=mid-1;
			}else {
				l=mid+1;
			}
		}
		ans+=(i-ind);
	}
	pw.print(ans);
}
